  navy:      "1E3A5F",  // header bar
  teal:      "0D9488",  // accent
  teal2:     "14B8A6",  // accent lighter
  mint:      "5EEAD4",  // highlight
  white:     "FFFFFF",
  offwhite:  "E2E8F0",
  slate:     "64748B",
  dark_txt:  "1E293B",
  muted:     "94A3B8",
  gold:      "F59E0B",
  coral:     "F97316",
  purple:    "7C3AED",
