nter\", margin: 0\n  });\n  s.addText(\"hermes-agent\\nin 24 hours\", {\n    x: 7.5, y: 1.72, w: 2.15, h: 0.48,\n    fontSize: 12, fontFace: \"Calibri\",\n    color: C.white, align: \"center\", margin: 0\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 7.5, y: 2.55, w: 2.15, h: 1.1,\n    fill: { color: C.gold },\n    line: { color: C.gold, width: 0 }\n  });\n  s.addText(\"42 Pushes\", {\n    x: 7.5, y: 2.6, w: 2.15, h: 0.6,\n    fontSize: 26, fontFace: \"Calibri\", bold: true,\n    color: C.dark_txt, align: \"center\", margin: 0\n  });\n  s.addText(\"multica: 35 pushes\\n(runner-up)\", {\n    x: 7.5, y: 3.15, w: 2.15, h: 0.42,\n    fontSize: 11, fontFace: \"Calibri\",\n    color: C.dark_txt, align: \"center\", margin: 0\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 7.5, y: 3.9, w: 2.15, h: 1.1,\n    fill: { color: \"E2E8F0\" },\n    line: { color: C.slate, width: 1 }\n  });\n  s.addText(\"8 of 20 repos\", {\n    x: 7.5, y: 3.95, w: 2.15, h: 0.5,\n    fontSize: 20, fontFace: \"Calibri\", bold: true,\n    color: C.dark_txt, align: \"center\", margin: 0\n  });\n  s.addText(\"have ZERO PRs\\n(early-stage hype)\", {\n    x: 7.5, y: 4.42, w: 2.15, h: 0.5,\n    fontSize: 11, fontFace: \"Calibri\",\n    color: C.slate, align: \"center\", margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────────────────\n// SLIDE 8: Key Takeaways\n// ─────────────────────────────────────────────────────────\n{\n  const s = pres.addSlide();\n  s.background = { color: C.bg_dark };\n\n  // Full-width top section\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0, y: 0, w: 10, h: 1.1,\n    fill: { color: \"0F2540\" }, line: { color: \"0F2540\", width: 0 }\n  });\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0, y: 1.1, w: 10, h: 0.04,\n    fill: { color: C.teal }, line: { color: C.teal, width: 0 }\n  });\n  s.addText(\"Key Takeaways: AI Coding Agents Are GitHub's Hottest Category\", {\n    x: 0.4, y: 0.1, w: 9.2, h: 0.9,\n    fontSize: 24, fontFace: \"Calibri\", 