const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";
pres.author = "OSSInsight Analysis";

// Color palette: Dark navy/midnight theme with teal accent
const C = {
  bg_dark:   "0F172A",  // slide bg (dark)
  bg_light:  "F8FAFC",  // content slides bg
  navy:      "1E3A5F",  // header bar
  teal:      "0D9488",  // accent
  teal2:     "14B8A6",  // accent lighter
  mint:      "5EEAD4",  // highlight
  white:     "FFFFFF",
  offwhite:  "E2E8F0",
  slate:     "64748B",
  dark_txt:  "1E293B",
  muted:     "94A3B8",
  gold:      "F59E0B",
  coral:     "F97316",
  purple:    "7C3AED",
  card_bg:   "FFFFFF",
  bar1:      "0D9488",
  bar2:      "14B8A6",
  bar3:      "5EEAD4",
  bar4:      "0F766E",
  bar5:      "99F6E4",
};

// ─────────────────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

  // Top band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.18, y: 0, w: 9.82, h: 0.08,
    fill: { color: C.teal2 }, line: { color: C.teal2, width: 0 }
  });

  // Decorative large circle (right bg)
  s.addShape(pres.shapes.OVAL, {
    x: 6.5, y: -1.2, w: 4.5, h: 4.5,
    fill: { color: "1E3A5F", transparency: 60 },
    line: { color: "1E3A5F", width: 0 }
  });
  s.addShape(pres.shapes.OVAL, {
    x: 7.2, y: 2.8, w: 3.5, h: 3.5,
    fill: { color: "0D9488", transparency: 75 },
    line: { color: "0D9488", width: 0 }
  });

  // Title
  s.addText("GitHub Trending Repos Snapshot", {
    x: 0.5, y: 1.0, w: 9.0, h: 0.8,
    fontSize: 38, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", margin: 0
  });
  s.addText("The Rise of AI Coding Agents & Claude Code Skills", {
    x: 0.5, y: 1.85, w: 9.0, h: 0.6,
    fontSize: 22, fontFace: "Calibri", bold: false,
    color: C.mint, align: "left", margin: 0
  });

  // Divider line
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 2.6, w: 5.5, h: 0.04,
    fill: { color: C.slate }, line: { color: C.slate, width: 0 }
  });

  // Subtitle / context
  s.addText("Analysis of the Top 20 Trending GitHub Repositories — Past 24 Hours", {
    x: 0.5, y: 2.75, w: 8.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: C.offwhite, align: "left", margin: 0
  });

  // Data source badge
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.35, w: 3.4, h: 0.5,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  s.addText("Powered by OSSInsight  •  10.6B+ GitHub Events", {
    x: 0.5, y: 3.35, w: 3.4, h: 0.5,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: C.white, align: "center", valign: "middle", margin: 0
  });

  // Date
  s.addText("April 2026", {
    x: 0.5, y: 4.05, w: 4, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: C.muted, align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────────────────
// SLIDE 2: Platform Overview (OSSInsight)
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Header bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.85, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

  s.addText("OSSInsight Tracks 10.6 Billion GitHub Events in Real Time", {
    x: 0.4, y: 0, w: 9.2, h: 0.85,
    fontSize: 22, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle", margin: 0
  });

  // Big stat callouts - 3 cards
  const stats = [
    { val: "10.6B+", lbl: "GitHub Events Tracked", icon: "★" },
    { val: "Real-Time", lbl: "Analytics Platform", icon: "⚡" },
    { val: "Free", lbl: "Open-Access Intelligence", icon: "✓" },
  ];
  const cardW = 2.8, cardH = 1.8, startX = 0.4, cardY = 1.1, gap = 0.25;
  stats.forEach((st, i) => {
    const cx = startX + i * (cardW + gap);
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: C.navy },
      line: { color: C.teal, width: 2 }
    });
    s.addText(st.val, {
      x: cx, y: cardY + 0.2, w: cardW, h: 0.8,
      fontSize: 34, fontFace: "Calibri", bold: true,
      color: C.mint, align: "center", margin: 0
    });
    s.addText(st.lbl, {
      x: cx, y: cardY + 1.0, w: cardW, h: 0.6,
      fontSize: 13, fontFace: "Calibri",
      color: C.offwhite, align: "center", margin: 0
    });
  });

  // Scoring formula box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.15, w: 9.2, h: 0.7,
    fill: { color: "132130" },
    line: { color: C.teal2, width: 1 }
  });
  s.addText("Trending Score Formula:  Total Score = Stars Score + Forks Score + Base Score", {
    x: 0.4, y: 3.15, w: 9.2, h: 0.7,
    fontSize: 15, fontFace: "Consolas", bold: true,
    color: C.mint, align: "center", valign: "middle", margin: 0
  });

  // Metrics tracked
  s.addText("Metrics tracked: Stars · Commits · Pull Requests · Issues · Contributors · Reviews · Forks · Pushes", {
    x: 0.4, y: 4.0, w: 9.2, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: C.muted, align: "center", margin: 0
  });

  s.addText("Source: ossinsight.io", {
    x: 0.4, y: 5.1, w: 9.2, h: 0.3,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.slate, align: "right", margin: 0
  });
}

// ─────────────────────────────────────────────────────────
// SLIDE 3: Top 5 Trending Repos — Horizontal Bar Chart
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_light };

  // Header
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.85, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
