    x: 0.4, y: 0, w: 9.2, h: 0.85,
    fontSize: 20, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle", margin: 0
  });

  // Repos in correct rank order (1-5), ascending for horizontal bar (bottom = #1)
  const repos = [
    { name: "claude-code-best-practice (#5)", stars: 304, forks: 23, pushes: 0, prs: 0 },
    { name: "caveman (#4)",                   stars: 300, forks: 11, pushes: 1, prs: 1 },
    { name: "awesome-design-md (#3)",          stars: 615, forks: 48, pushes: 1, prs: 0 },
    { name: "graphify (#2)",                   stars: 742, forks: 50, pushes: 6, prs: 5 },
    { name: "hermes-agent (#1)",               stars: 1347, forks: 101, pushes: 42, prs: 78 },
  ];

  s.addChart(pres.charts.BAR, [
    { name: "Stars",  labels: repos.map(r => r.name), values: repos.map(r => r.stars) },
    { name: "Forks",  labels: repos.map(r => r.name), values: repos.map(r => r.forks) },
    { name: "Pushes", labels: repos.map(r => r.name), values: repos.map(r => r.pushes) },
    { name: "PRs",    labels: repos.map(r => r.name), values: repos.map(r => r.prs) },
  ], {
    x: 0.3, y: 1.0, w: 9.4, h: 4.3,
