    barGrouping: "clustered",
    chartColors: [C.teal, "06B6D4", C.gold, C.coral],
    chartArea: { fill: { color: C.bg_light }, roundedCorners: false },
    plotArea: { fill: { color: C.bg_light } },
    catAxisLabelColor: C.dark_txt,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: C.slate,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "D1D5DB", size: 0.5 },
    catGridLine: { style: "none" },
