const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";
pres.author = "OSSInsight Analysis";

const C = {
  bg_dark:  "0F172A",
  bg_light: "F8FAFC",
  navy:     "1E3A5F",
  teal:     "0D9488",
  teal2:    "14B8A6",
  teal3:    "0F766E",
  mint:     "5EEAD4",
  white:    "FFFFFF",
  offwhite: "E2E8F0",
  slate:    "64748B",
  dark_txt: "1E293B",
  muted:    "94A3B8",
  gold:     "F59E0B",
  coral:    "F97316",
  purple:   "7C3AED",
  card_dk:  "132130",
};

// ─────────────────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  // Top band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.18, y: 0, w: 9.82, h: 0.08,
    fill: { color: C.teal2 }, line: { color: C.teal2, width: 0 }
  });

  // Decorative circles — offset so they look intentional
  s.addShape(pres.shapes.OVAL, {
    x: 7.0, y: 2.5, w: 3.2, h: 3.2,
    fill: { color: "1E3A5F", transparency: 55 },
    line: { color: "1E3A5F", width: 0 }
  });
  s.addShape(pres.shapes.OVAL, {
    x: 6.0, y: 0.8, w: 2.5, h: 2.5,
    fill: { color: "0D9488", transparency: 72 },
    line: { color: "0D9488", width: 0 }
  });

  // Title area - vertically centered
  s.addText("GitHub Trending Repos Snapshot", {
    x: 0.5, y: 1.3, w: 8.8, h: 0.8,
    fontSize: 36, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", margin: 0
  });
  s.addText("The Rise of AI Coding Agents & Claude Code Skills", {
    x: 0.5, y: 2.15, w: 8.8, h: 0.55,
    fontSize: 21, fontFace: "Calibri",
    color: C.mint, align: "left", margin: 0
  });

  // Divider
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 2.85, w: 5.0, h: 0.04,
    fill: { color: C.slate }, line: { color: C.slate, width: 0 }
  });

  s.addText("Analysis of the Top 20 Trending GitHub Repositories — Past 24 Hours", {
    x: 0.5, y: 3.0, w: 8.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: C.offwhite, align: "left", margin: 0
  });

  // Badge — wide enough for one line
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.6, w: 4.5, h: 0.45,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  s.addText("Powered by OSSInsight  •  10.6B+ GitHub Events", {
    x: 0.5, y: 3.6, w: 4.5, h: 0.45,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: C.white, align: "center", valign: "middle", margin: 0
  });

  s.addText("April 2026", {
    x: 0.5, y: 4.25, w: 4, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: C.muted, align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────────────────
// SLIDE 2: Platform Overview
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.85, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  // Reduced font to avoid wrap
  s.addText("OSSInsight: 10.6 Billion GitHub Events Tracked in Real Time", {
    x: 0.4, y: 0, w: 9.2, h: 0.85,
    fontSize: 21, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle", margin: 0
  });

  const stats = [
    { val: "10.6B+", lbl: "GitHub Events Tracked" },
    { val: "Real-Time", lbl: "Analytics Platform" },
    { val: "Free", lbl: "Open-Access Intelligence" },
  ];
  const cardW = 2.8, cardH = 1.9, startX = 0.4, cardY = 1.05, gap = 0.25;
  stats.forEach((st, i) => {
    const cx = startX + i * (cardW + gap);
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: C.navy },
      line: { color: C.teal, width: 2 }
    });
    // Top color accent bar per card
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.07,
      fill: { color: C.teal }, line: { color: C.teal, width: 0 }
    });
    s.addText(st.val, {
      x: cx, y: cardY + 0.25, w: cardW, h: 0.9,
      fontSize: 34, fontFace: "Calibri", bold: true,
      color: C.mint, align: "center", margin: 0
    });
    s.addText(st.lbl, {
      x: cx, y: cardY + 1.2, w: cardW, h: 0.55,
      fontSize: 13, fontFace: "Calibri",
      color: C.offwhite, align: "center", margin: 0
    });
  });

  // Formula box — reduced font to fit single line
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.2, w: 9.2, h: 0.65,
    fill: { color: "0A1A28" },
    line: { color: C.teal2, width: 1 }
  });
  s.addText("Total Score  =  Stars Score  +  Forks Score  +  Base Score", {
    x: 0.4, y: 3.2, w: 9.2, h: 0.65,
    fontSize: 14, fontFace: "Consolas", bold: true,
    color: C.mint, align: "center", valign: "middle", margin: 0
  });

  s.addText("Metrics: Stars · Commits · Pull Requests · Issues · Contributors · Reviews · Forks · Pushes", {
    x: 0.4, y: 4.05, w: 9.2, h: 0.38,
    fontSize: 13, fontFace: "Calibri",
    color: C.muted, align: "center", margin: 0
  });

  s.addText("Source: ossinsight.io", {
    x: 0.4, y: 5.15, w: 9.2, h: 0.28,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.slate, align: "right", margin: 0
  });
}

// ─────────────────────────────────────────────────────────
// SLIDE 3: Top 5 Repos — Horizontal Bar Chart
// ─────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.bg_light };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.85, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  s.addText("hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score", {
    x: 0.4, y: 0, w: 9.2, h: 0.85,
    fontSize: 20, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle", margin: 0
  });

  // Repos in correct rank order (1-5), ascending for horizontal bar (bottom = #1)
  const repos = [
    { name: "claude-code-best-practice (#5)", stars: 304, forks: 23, pushes: 0, prs: 0 },
    { name: "caveman (#4)",                   stars: 300, forks: 11, pushes: 1, prs: 1 },
